-- Owner-requested prepared discussions. Editorial entries never impersonate member accounts.
alter table public.comments alter column author_id drop not null;
alter table public.comments add column editorial_key text unique;
alter table public.comments add constraint comments_author_kind check (
  (author_id is not null and editorial_key is null) or
  (author_id is null and editorial_key is not null and char_length(editorial_key) between 1 and 100)
);
-- Existing column-level INSERT grants and RLS allow members to write only their own comments.
insert into public.comments (catalog_id, author_id, editorial_key, body)
select entry.catalog_id, null::uuid, entry.editorial_key, entry.body
from (values
  ('fox-costume-in-motion', 'fox-costume-in-motion:discussion:01', 'The tail silhouette is the star of this costume.'),
