  ('costume-meetup-hug', 'costume-meetup-hug:discussion:25', 'Warm greetings do not need elaborate staging.'),
  ('costume-meetup-hug', 'costume-meetup-hug:discussion:26', 'What is your favorite respectful way to greet a costumed performer?'),
  ('ask-before-you-snap', 'ask-before-you-snap:discussion:01', 'Asking before a photo is always a good place to start.'),
